<?php
require_once '../config/database.php'; require_once '../includes/auth.php'; require_role('student');$page_title='Мои оценки';
$q=$pdo->prepare('SELECT id FROM students WHERE user_id=?');$q->execute([$_SESSION['user']['id']]);$sid=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT gr.*,s.name subject_name,CONCAT(COALESCE(t.surname,''),' ',COALESCE(t.name,'')) teacher_name FROM grades gr JOIN subjects s ON s.id=gr.subject_id LEFT JOIN teachers t ON t.id=gr.teacher_id WHERE gr.student_id=? ORDER BY gr.grade_date DESC,gr.id DESC");$q->execute([$sid]);$rows=$q->fetchAll();
$q=$pdo->prepare('SELECT s.name subject_name,ROUND(AVG(gr.grade),2) avg_grade,COUNT(*) count_grade FROM grades gr JOIN subjects s ON s.id=gr.subject_id WHERE gr.student_id=? GROUP BY s.id ORDER BY s.name');$q->execute([$sid]);$summary=$q->fetchAll();
$avg=$rows?round(array_sum(array_column($rows,'grade'))/count($rows),2):0;include '../includes/header.php';?>
<div class="cards"><div class="card"><div class="kpi-icon">⭐</div><div class="label">Средний балл</div><div class="value"><?=$avg?:'—'?></div><div class="subvalue">по всем предметам</div></div><div class="card"><div class="kpi-icon">📝</div><div class="label">Всего оценок</div><div class="value"><?=count($rows)?></div></div></div>
<div class="panel"><h2>Средний балл по предметам</h2><?php if($summary):?><div class="table-wrap"><table><tr><th>Предмет</th><th>Количество</th><th>Средний балл</th></tr><?php foreach($summary as $r):?><tr><td><?=htmlspecialchars($r['subject_name'])?></td><td><?=$r['count_grade']?></td><td><b><?=$r['avg_grade']?></b></td></tr><?php endforeach;?></table></div><?php else:?><div class="empty-state"><div class="emoji">⭐</div>Оценок пока нет.</div><?php endif;?></div>
<div class="panel" style="margin-top:20px"><div class="section-head"><h2>Все оценки</h2><input class="search" id="q" oninput="filterTable('q','gradesTable')" placeholder="🔍 Поиск по предмету"></div><div class="table-wrap"><table id="gradesTable"><tbody><tr><th>Дата</th><th>Предмет</th><th>Оценка</th><th>Преподаватель</th><th>Комментарий</th></tr><?php foreach($rows as $r):?><tr><td><?=date('d.m.Y',strtotime($r['grade_date']))?></td><td><b><?=htmlspecialchars($r['subject_name'])?></b></td><td><span class="grade grade-<?=$r['grade']?>"><?=$r['grade']?></span></td><td><?=htmlspecialchars(trim($r['teacher_name']))?:'—'?></td><td><?=htmlspecialchars($r['comment'])?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include '../includes/footer.php';?>
